-- Tipos de precios, tipos de productos y precios de la organización 3 (Futura Farma - Mavisa), de los
-- archivos «ACT_TIPOS_PRECIOS.xls» (10: 4 de la 3-01 y 6 de la 3-02), «ACT_TIPOS_PRODUCTOS.xls» (100: 12 de la 3-01 y 88 de la 3-02)
-- y «ACT_PRECIOS.xls» (898 precios de 302 productos: 581 de la 3-01 y 317 de la 3-02).
--   1. Si ya existe en la localidad (mismo código) NO se crea: se actualiza.
--   2. Columnas nuevas (vienen en el archivo y no estaban en la base de datos):
--      tipos_precio: factor_valor (FACTOR numérico; 1 = Normal).
--      tipos_producto: las 12 cuentas y versiones del sistema anterior (cuenta_inventarios_anterior,
--      cuenta_facturacion_anterior, version_anterior, cuenta_contable_anterior, cuenta_gasto_anterior,
--      version_gasto_anterior, cuenta_fac_anterior, version_fac_anterior, cuenta_traslado_anterior,
--      version_traslado_anterior, cuenta_maquila_anterior y version_maquila_anterior); las de inventarios y
--      facturación se ligan si existen en el catálogo de la localidad.
--      producto_precios: localidad_id, producto_codigo, fecha, precio_alterno, pct_descuento, estado,
--      usuario_ingresa, fecha_ingresa, usuario_modifica, fecha_modifica, descuento_aplicado, pct_utilidad
--      y precio_base.
--   Precios: los productos aún no están migrados, así que cada precio se guarda con el código del producto
--   (producto_codigo) y sin producto_id; al crear el producto (o al migrar ACT_PRODUCTOS) sus precios se
--   ligan solos, por localidad y código. Un precio se identifica por localidad, producto y tipo de precio.
--   Equivalencias: ESTADO A/I = activo/inactivo; las fechas vienen como número de Excel. La localidad 1 y 2
--   del archivo son la 3-01 y la 3-02; el tipo de producto va en su clasificación (por código).
--   Tipos de precio con la descripción repetida en la localidad (la base exige que no se repita): la segunda
--   lleva « (2)»: 3-02 tipo 6 DISTRIBUIDOR.
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.
-- Se ejecuta después del script 102.

alter table public.tipos_precio add column if not exists factor_valor numeric(12, 4);
alter table public.tipos_producto add column if not exists cuenta_inventarios_anterior text;
alter table public.tipos_producto add column if not exists cuenta_facturacion_anterior text;
alter table public.tipos_producto add column if not exists version_anterior integer;
alter table public.tipos_producto add column if not exists cuenta_contable_anterior text;
alter table public.tipos_producto add column if not exists cuenta_gasto_anterior text;
alter table public.tipos_producto add column if not exists version_gasto_anterior integer;
alter table public.tipos_producto add column if not exists cuenta_fac_anterior text;
alter table public.tipos_producto add column if not exists version_fac_anterior integer;
alter table public.tipos_producto add column if not exists cuenta_traslado_anterior text;
alter table public.tipos_producto add column if not exists version_traslado_anterior integer;
alter table public.tipos_producto add column if not exists cuenta_maquila_anterior text;
alter table public.tipos_producto add column if not exists version_maquila_anterior integer;

alter table public.producto_precios alter column producto_id drop not null;
alter table public.producto_precios add column if not exists localidad_id bigint references public.localidades (id);
alter table public.producto_precios add column if not exists producto_codigo integer;
alter table public.producto_precios add column if not exists fecha timestamptz;
alter table public.producto_precios add column if not exists precio_alterno numeric(18, 4);
alter table public.producto_precios add column if not exists pct_descuento numeric(7, 2);
alter table public.producto_precios add column if not exists estado text not null default 'ACTIVO';
alter table public.producto_precios add column if not exists usuario_ingresa text;
alter table public.producto_precios add column if not exists fecha_ingresa timestamptz;
alter table public.producto_precios add column if not exists usuario_modifica text;
alter table public.producto_precios add column if not exists fecha_modifica timestamptz;
alter table public.producto_precios add column if not exists descuento_aplicado numeric(18, 4);
alter table public.producto_precios add column if not exists pct_utilidad numeric(7, 2);
alter table public.producto_precios add column if not exists precio_base numeric(18, 4);
alter table public.producto_precios drop constraint if exists producto_precios_estado_check;
alter table public.producto_precios add constraint producto_precios_estado_check check (estado in ('ACTIVO', 'INACTIVO'));
alter table public.producto_precios drop constraint if exists producto_precios_producto_o_codigo;
alter table public.producto_precios add constraint producto_precios_producto_o_codigo check (producto_id is not null or (producto_codigo is not null and localidad_id is not null));
create unique index if not exists producto_precios_codigo_tipo on public.producto_precios (localidad_id, producto_codigo, tipo_precio_id) where producto_codigo is not null;
-- Precios existentes: su localidad y código salen del producto.
update public.producto_precios pp set localidad_id = p.localidad_id, producto_codigo = p.codigo
from public.productos p where p.id = pp.producto_id and (pp.localidad_id is null or pp.producto_codigo is null);

-- Detalle de productos (script 59): el precio sin producto (migrado) usa su propia localidad; con producto,
-- la localidad y el código salen del producto.
create or replace function public.validar_producto_detalle() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_loc bigint;
begin
  if new.producto_id is not null then
    select localidad_id into v_loc from public.productos where id = new.producto_id;
  end if;
  if tg_table_name = 'producto_proveedores' then
    if not exists (select 1 from public.proveedores p where p.id = new.proveedor_id and p.localidad_id = v_loc) then raise exception 'El proveedor no es de la localidad del producto.'; end if;
    new.codigo_proveedor := nullif(upper(trim(new.codigo_proveedor)), '');
  else
    if new.producto_id is not null then
      new.localidad_id := v_loc;
      select codigo into new.producto_codigo from public.productos where id = new.producto_id;
    end if;
    if not exists (select 1 from public.tipos_precio t where t.id = new.tipo_precio_id and t.localidad_id = new.localidad_id) then raise exception 'El tipo de precio no es de la localidad del producto.'; end if;
  end if;
  return new;
end;
$$;

-- Al crear un producto se le ligan los precios migrados con su código en la misma localidad.
create or replace function public.ligar_precios_migrados() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.producto_precios set producto_id = new.id
  where producto_id is null and localidad_id = new.localidad_id and producto_codigo = new.codigo;
  return null;
end;
$$;
drop trigger if exists productos_ligar_precios on public.productos;
create trigger productos_ligar_precios after insert on public.productos for each row execute function public.ligar_precios_migrados();

do $migra$
declare
  v_org bigint;
  r record;
  v_loc bigint;
  v_cla bigint;
  v_tp bigint;
  v_prod bigint;
  v_ci bigint; v_cf bigint;
  v_nuevo boolean;
  a_n int := 0; a_a int := 0; b_n int := 0; b_a int := 0; b_s int := 0; c_n int := 0; c_a int := 0; c_s int := 0; c_l int := 0;
begin
  select id into v_org from public.organizaciones where codigo = '3';
  if v_org is null then raise notice 'No existe la organización 3.'; return; end if;

  -- Tipos de precio.
  for r in select * from (values
    (1, 1, 'HOSPITALARIO', 0, 0, 1, false),
    (1, 2, 'ESPECIAL', 0, 0, 1, true),
    (1, 3, 'MINORISTA', 0, 0, 1, true),
    (1, 4, 'DISTRIBUIDOR', 0, 0, 1, true),
    (2, 1, 'PRECIO TRASLADO', 0, 0, 1, false),
    (2, 2, 'DISTRIBUIDOR', 35, 0, 1, true),
    (2, 3, 'MAYORISTA', 45, 0, 1, true),
    (2, 4, 'ESPECIAL', 50, 0, 1, true),
    (2, 6, 'DISTRIBUIDOR (2)', 20, 0, 1, true),
    (2, 7, 'CH PRECIO FARMACIA', 35, 0, 1, false)) as x(loc, codigo, nombre, utilidad, descuento, factor, activo) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    if v_loc is null then raise notice 'No existe la localidad 3-0%.', r.loc; continue; end if;
    insert into public.tipos_precio (organizacion_id, localidad_id, codigo, nombre, pct_utilidad, pct_descuento, factor, factor_valor, activo)
    values (v_org, v_loc, r.codigo, r.nombre, r.utilidad, r.descuento, 'NORMAL', r.factor, r.activo)
    on conflict (localidad_id, codigo) do update set nombre = excluded.nombre, pct_utilidad = excluded.pct_utilidad,
      pct_descuento = excluded.pct_descuento, factor_valor = excluded.factor_valor, activo = excluded.activo
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then a_n := a_n + 1; else a_a := a_a + 1; end if;
  end loop;

  -- Tipos de producto (en su clasificación, por código).
  for r in select * from (values
