    (2, 77, 'KETOROLACO TROMETAMINA', 1, 'KET', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 78, 'CASPOFUNGINA', 1, 'CAS', null, null, null, null, null, null, null, null, null, null, null, null),
