    (2, 80, 'LEVETIRACETAM', 1, 'LEV', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 81, 'SITAGLIPTINA', 1, 'SIT', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 82, 'IBUPROFENO', 1, 'IBU', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 83, 'PARACETAMOL', 1, 'PRT', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 84, 'METFORMINA', 1, 'MET', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 85, 'CISPLATINO', 1, 'CIS', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 86, 'CEFAZOLINA', 1, 'CEZ', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 87, 'CISATRACURIO', 1, 'CIS', null, null, null, null, null, null, null, null, null, null, null, null),
    (2, 88, 'DESCARTABLES', 1, 'DES', null, null, null, null, null, null, null, null, null, null, null, null)) as x(loc, codigo, nombre, clasificacion, siglas, c_inv, c_fac, ver, c_cont, c_gas, ver_gas, c_fac2, ver_fac, c_tras, ver_tras, c_maq, ver_maq) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select id into v_cla from public.clasificaciones_producto where localidad_id = v_loc and codigo = r.clasificacion;
